with unpacked as (select id, service, level, payload_json, context, cast((status_code & 1) != 0 as int) as has_fault, coalesce(context['version'], 'direct') as version_or_default, array_contains(map_keys(context), 'region') as has_region from app_logs) select level, case when has_fault >= 1 then 'PREMIUM' else 'STANDARD' end as has_fault_tier, count_if(level = 'ERROR') as error_events, sum(has_fault) filter (where level = 'INFO') as info_total_has_fault, count(distinct level) as distinct_levels, count(*) as row_count, sum(case when service = 'auth' then has_fault else 0 end) as auth_has_fault, sort_array(collect_set(service)) as service_list, rank() over (partition by level order by count_if(level = 'ERROR') desc) as error_events_rank from unpacked group by level, case when has_fault >= 1 then 'PREMIUM' else 'STANDARD' end order by has_fault_tier desc nulls last;
